import{_ as t,o as a,c as n,a2 as i}from"./chunks/framework.lxr64Vqo.js";const p=JSON.parse('{"title":"📡 Telegram Channels & Indexing","description":"","frontmatter":{},"headers":[],"relativePath":"guide/channels-setup.md","filePath":"guide/channels-setup.md","lastUpdated":1795112636000}'),o={name:"guide/channels-setup.md"};function l(r,e,d,s,c,h){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="📡-telegram-channels-indexing" tabindex="-1">📡 Telegram Channels &amp; Indexing <a class="header-anchor" href="#📡-telegram-channels-indexing" aria-label="Permalink to &quot;📡 Telegram Channels &amp; Indexing&quot;">​</a></h1><p>NoxMedia transforms your private and public Telegram channels into a unified, beautifully organized streaming library.</p><hr><h2 id="🔗-adding-channels" tabindex="-1">🔗 Adding Channels <a class="header-anchor" href="#🔗-adding-channels" aria-label="Permalink to &quot;🔗 Adding Channels&quot;">​</a></h2><p>NoxMedia supports multiple channel link formats:</p><ol><li><strong>Public Channels</strong>: <ul><li>Enter the channel username: <code>@channelname</code> or <code>https://t.me/channelname</code>.</li></ul></li><li><strong>Private Channels</strong>: <ul><li>Enter your invite link: <code>https://t.me/+inviteCode...</code> or <code>https://t.me/joinchat/...</code>.</li><li>Your logged-in Telegram account must already be a member of the channel.</li></ul></li><li><strong>Channel ID</strong>: <ul><li>Enter the raw channel identifier (e.g. <code>-1001234567890</code>).</li></ul></li></ol><hr><h2 id="🧠-smart-metadata-extraction" tabindex="-1">🧠 Smart Metadata Extraction <a class="header-anchor" href="#🧠-smart-metadata-extraction" aria-label="Permalink to &quot;🧠 Smart Metadata Extraction&quot;">​</a></h2><p>When you index a channel, NoxMedia runs an intelligent title parser that cleans up release names, stripping clutter while preserving key media tags:</p><ul><li><strong>Movie / Series Title &amp; Year</strong>: Parsed from file names, captions, or message headers.</li><li><strong>Season &amp; Episode Numbers</strong>: Supports formats like <code>S01E05</code>, <code>1x05</code>, <code>E05</code>, or multi-episode packs.</li><li><strong>Resolution &amp; Video Quality</strong>: Identifies <code>2160p (4K)</code>, <code>1080p (FHD)</code>, <code>720p (HD)</code>, <code>Remux</code>, <code>WEB-DL</code>, <code>BluRay</code>.</li><li><strong>Codecs &amp; HDR</strong>: Flags <code>HEVC / H.265</code>, <code>AV1</code>, <code>HDR10</code>, <code>Dolby Vision (DV)</code>.</li><li><strong>Audio Tracks</strong>: Detects dual-audio / multi-audio languages (<code>Hindi</code>, <code>English</code>, <code>Japanese</code>, <code>5.1 AAC</code>, <code>Atmos</code>).</li></ul><hr><h2 id="🌐-metadata-providers" tabindex="-1">🌐 Metadata Providers <a class="header-anchor" href="#🌐-metadata-providers" aria-label="Permalink to &quot;🌐 Metadata Providers&quot;">​</a></h2><p>NoxMedia queries trusted databases to enrich your media with high-resolution posters, backdrops, cast information, and plot summaries:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Media Type</th><th style="text-align:left;">Primary Provider</th><th style="text-align:left;">Fallback / Anime</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Movies</strong></td><td style="text-align:left;">TheMovieDatabase (TMDB)</td><td style="text-align:left;">File metadata &amp; title search</td></tr><tr><td style="text-align:left;"><strong>TV Shows</strong></td><td style="text-align:left;">TheTVDB &amp; TMDB</td><td style="text-align:left;">Episode titles &amp; air dates</td></tr><tr><td style="text-align:left;"><strong>Anime</strong></td><td style="text-align:left;">Kitsu.io &amp; AniList</td><td style="text-align:left;">Japanese / Romaji titles &amp; season mapping</td></tr></tbody></table><hr><h2 id="✍️-manual-match-overrides" tabindex="-1">✍️ Manual Match &amp; Overrides <a class="header-anchor" href="#✍️-manual-match-overrides" aria-label="Permalink to &quot;✍️ Manual Match &amp; Overrides&quot;">​</a></h2><p>If a Telegram post has an obscure or unstandardized name:</p><ol><li>Open NoxMedia and go to the <strong>Index / Library</strong> screen.</li><li>Locate the media item.</li><li>Tap the <strong>Three Dots (⋮)</strong> → <strong>Manual Match</strong>.</li><li>Search for the exact movie or show title on TMDB.</li><li>Select the correct entry. NoxMedia will re-link all episodes and artwork immediately.</li></ol><hr><h2 id="🔄-automatic-channel-updates" tabindex="-1">🔄 Automatic Channel Updates <a class="header-anchor" href="#🔄-automatic-channel-updates" aria-label="Permalink to &quot;🔄 Automatic Channel Updates&quot;">​</a></h2><p>NoxMedia listens for new posts in your connected channels. When new episodes or movies are uploaded to Telegram, they are indexed in the background and become available in your streaming clients in seconds.</p>',21)])])}const u=t(o,[["render",l]]);export{p as __pageData,u as default};
